#!/bin/bash
fail=0
bash bin/render event | grep -q 'action="?action=save"' || { echo "render"; fail=1; }
# every rendered form action must use only query keys allowed by the Cirrus function URL
bash bin/render event | grep -o 'action="[^"]*"' | grep -o '?[^=]*' | grep -qv '^?[A-Za-z0-9_.-]*$' && { echo "render: invalid query key"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/orders/5012/refund?action=refund' | grep -q '^200 refund' || { echo "handle refund"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh

